<?php require_once __DIR__ . '/../bootstrap.php'; db(); require_admin(); if($_SERVER['REQUEST_METHOD']!=='POST') redirect('dashboard.php'); check_csrf();$id=(int)$_POST['id'];$status=$_POST['status']??'';if(!in_array($status,['new','reviewed','resolved'],true))exit('Invalid status');$s=db()->prepare("UPDATE feedback SET status=? WHERE id=?");$s->execute([$status,$id]);redirect('feedback.php?id='.$id);